// Pure detect/filter logic, kept free of the mods API so it can be unit tested.
import { analyze, simpleCommands } from './shell.ts'

export interface Rule {
  id: string
  tool: string
  // Returns the deny reason when the call should be blocked, otherwise null
  check: (e: { command?: string }) => string | null
}

// find's leading options are -H -L -P, -D <debugopts> and -O<level>; the
// starting points follow, up to the first token of the expression.
function findStartPoints(args: string[]): string[] {
  let i = 0
  for (; i < args.length; i++) {
    if (args[i] === '-D') i++
    else if (!/^-[HLPO]/.test(args[i] ?? '')) break
  }
  if (args[i] === '--') i++
  const paths: string[] = []
  for (; i < args.length; i++) {
    const a = args[i]!
    if (a.startsWith('-') || a === '(' || a === '!') break
    paths.push(a)
  }
  return paths
}

// Primaries that consume the next token as a value, which may itself look like an option
const FIND_VALUE_PRIMARIES = new Set([
  '-name', '-iname', '-path', '-ipath', '-wholename', '-iwholename', '-regex', '-iregex', '-lname', '-ilname',
  '-type', '-xtype', '-user', '-group', '-perm', '-size', '-newer', '-anewer', '-cnewer', '-samefile',
  '-mtime', '-atime', '-ctime', '-mmin', '-amin', '-cmin', '-links', '-inum', '-uid', '-gid', '-used',
  '-fstype', '-printf', '-fprintf', '-fprint', '-fprint0', '-fls', '-context', '-maxdepth', '-mindepth',
  '-newerXY',
])

// -mount is the traditional spelling of -xdev
function findStaysOnFilesystem(args: string[]): boolean {
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!
    if (a === '-xdev' || a === '-mount') return true
    if (/^-(exec|execdir|ok|okdir)$/.test(a)) {
      // The embedded command runs up to a lone ; or +
      while (i + 1 < args.length && args[i] !== ';' && args[i] !== '+') i++
    } else if (FIND_VALUE_PRIMARIES.has(a) || /^-newer[aBcmt][aBcmt]$/.test(a)) i++
  }
  return false
}

// `/*` expands to every top-level entry, which scans the whole filesystem too
const isFilesystemRoot = (p: string) => /^\/+(\.\/?)*\*?$/.test(p)

// pgrep options that take a value, so in `-uf` the f is a user name, not -f
const PGREP_ARG_OPTS = 'dFgGJOPrstTuU'

// pkill has no list-full option: its -a is not a thing, so `listFull` stays false
function pgrepFlags(args: string[], prog: string): { full: boolean; listFull: boolean } {
  let full = false
  let listFull = false
  for (const a of args) {
    if (a === '--') break
    if (a === '--full') full = true
    else if (a === '--list-full') listFull = true
    else if (/^-[^-]/.test(a)) {
      for (const ch of a.slice(1)) {
        if (ch === 'f') full = true
        else if (ch === 'a' && prog === 'pgrep') listFull = true
        else if (PGREP_ARG_OPTS.includes(ch)) break
      }
    }
  }
  return { full, listFull }
}

const GREPS = new Set(['grep', 'egrep', 'fgrep', 'rg'])

export const rules: Rule[] = [
  {
    id: 'monitor-disabled',
    tool: 'Monitor',
    check: () =>
      'Monitor is disabled. Use Bash with run_in_background to spawn a blocking waiter that exits on the next event.',
  },
  // Runs first: if the command can't be parsed, the rules below can't be trusted to see all of it
  {
    id: 'malformed-bash',
    tool: 'Bash',
    check: ({ command = '' }) => {
      const { errors } = analyze(command)
      return errors.length
        ? `Malformed bash command (${errors[0]}). Fix the syntax and retry.`
        : null
    },
  },
  {
    id: 'find-root',
    tool: 'Bash',
    check: ({ command = '' }) =>
      simpleCommands(command).some((c) => c.name === 'find' && findStartPoints(c.args).some(isFilesystemRoot))
        ? 'find rooted at / is disabled. Scan a specific directory instead.'
        : null,
  },
  {
    id: 'find-xdev',
    tool: 'Bash',
    check: ({ command = '' }) =>
      simpleCommands(command).some((c) => c.name === 'find' && !findStaysOnFilesystem(c.args))
        ? 'find must specify -xdev so it does not cross filesystem boundaries. To search several filesystems, issue a separate find -xdev per filesystem.'
        : null,
  },
  {
    id: 'pgrep-f',
    tool: 'Bash',
    check: ({ command = '' }) =>
      simpleCommands(command).some((c) => {
        if (c.name !== 'pgrep' && c.name !== 'pkill') return false
        const { full, listFull } = pgrepFlags(c.args, c.name)
        return full && !listFull
      })
        ? 'pgrep -f and pkill -f can match helper processes spawned by the harness (e.g. its bash -c wrapper), and pkill would kill them. Use pgrep -af, confirm each match cmdline, then kill by PID.'
        : null,
  },
  {
    id: 'pgrep-captured',
    tool: 'Bash',
    check: ({ command = '' }) =>
      simpleCommands(command).some((c) => c.name === 'pgrep' && c.captured)
        ? 'Do not capture pgrep output in a pipe or substitution ($(...), `...`, <(...)). Let pgrep print straight to stdout and read the result.'
        : null,
  },
  {
    id: 'until-grep',
    tool: 'Bash',
    check: ({ command = '' }) =>
      analyze(command).untilClauses.some((cmds) => cmds.some((c) => GREPS.has(c.name)))
        ? 'An "until grep ..." (or "while ! grep ...") loop never exits if the process writing the log silently dies. Watch the process instead: tail -f --pid=<PID> <log> | grep -m1 <pattern> (tail stops when the process exits, ending the pipeline either way). Run it with run_in_background.'
        : null,
  },
  {
    id: 'sudo',
    tool: 'Bash',
    check: ({ command = '' }) =>
      simpleCommands(command).some((c) => c.name === 'sudo' || c.wrappers.includes('sudo'))
        ? 'sudo is disabled: passwordless sudo is insecure, and a password prompt needs a TTY, which Bash processes spawned by Claude Code do not have. Use run0 instead, which shows the user a graphical auth prompt every time and does not cache authentication.'
        : null,
  },
]

// Quote a word the way a shell would need it, so the displayed command is unambiguous
const shellQuote = (w: string) => (/^[\w@%+=:,./-]+$/.test(w) ? w : `'${w.replace(/'/g, `'\\''`)}'`)

/** Every run0 invocation in `command`, as the full command line it will run
 *  (`run0 -u root systemctl restart x`), for showing to the user. */
export function run0Invocations(command: string): string[] {
  const out: string[] = []
  for (const c of simpleCommands(command)) {
    if (c.name === 'run0') out.push(['run0', ...c.args].map(shellQuote).join(' '))
    // Wrappers nested in wrappers (`env X=1 run0 ls`): each run0 reports its own tail
    c.wrappers.forEach((w, i) => {
      if (w === 'run0') out.push(c.wrapped[i]!.map(shellQuote).join(' '))
    })
  }
  return [...new Set(out)]
}

// The userConfig key that toggles a rule: its id with underscores
export const ruleKey = (id: string) => id.replace(/-/g, '_')

// Defaults live in the manifest's userConfig, which Claude Code fills into options
export const ruleEnabled = (options: Record<string, unknown> | undefined, id: string) =>
  options?.[ruleKey(id)] === true

// Monitor runs a shell command just like Bash, so the Bash rules apply to it too
const appliesTo = (r: Rule, tool: string) => r.tool === tool || (tool === 'Monitor' && r.tool === 'Bash')

export function firstDenialBy(tool: string, e: { command?: string; ws?: unknown }, options?: Record<string, unknown>): { rule: string; reason: string } | null {
  for (const r of rules) {
    if (!appliesTo(r, tool) || !ruleEnabled(options, r.id)) continue
    if (tool === 'Monitor' && r.tool === 'Bash' && typeof e.command !== 'string') {
      // A ws source streams a WebSocket and runs no shell, so there is nothing for the shell rules to check
      if (e.ws !== undefined) continue
      // Fail closed: with neither field the shell rules would be checking an empty string
      return { rule: 'monitor-no-command', reason: 'Monitor call has no command string that the Bash guard rules can check; refusing it rather than running it unchecked.' }
    }
    const reason = r.check(e)
    if (reason) return { rule: r.id, reason }
  }
  return null
}

export const firstDenial = (...args: Parameters<typeof firstDenialBy>): string | null => firstDenialBy(...args)?.reason ?? null

